<script setup lang="ts">import {computed,ref} from 'vue';export interface CommandOption {id:string;label:string;group?:string};const props=defineProps<{open:boolean;commands:CommandOption[]}>();const emit=defineEmits<{close:[];select:[id:string]}>();const query=ref('');const filtered=computed(()=>props.commands.filter(c=>(c.label+' '+(c.group||'')).toLowerCase().includes(query.value.toLowerCase())));function choose(id:string){emit('select',id);emit('close');}</script><template><Teleport to="body"><div v-if="open" class="vx-command-backdrop" @click.self="emit('close')"><section class="vx-command-palette" role="dialog" aria-modal="true" aria-label="Command palette" @keydown.esc="emit('close')"><input v-model="query" autofocus type="search" placeholder="Search actions…" aria-label="Search actions"/><button v-for="c in filtered" :key="c.id" type="button" @click="choose(c.id)"><small>{{c.group}}</small>{{c.label}}</button><p v-if="!filtered.length">No matching actions</p></section></div></Teleport></template>